let data,platform='all',selected=[];
const $=id=>document.getElementById(id);
const n=(v,d=2)=>v==null?'—':Number(v).toLocaleString('es-CO',{maximumFractionDigits:d});
const secs=v=>v==null?'—':v>=60000?`${n(v/60000)} min`:`${n(v/1000)} s`;
const date=v=>new Date(v).toLocaleString('es-CO',{timeZone:'America/Bogota',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});
const sum=(rows,key)=>rows.reduce((s,r)=>s+(r[key]??0),0);
const measured=rows=>rows.filter(r=>r.processing_ms>0 && r.photos!=null);
const outcomeLabel={search_completed:'Completada',search_cancelled:'Cancelada',search_failed:'Fallida',search_interrupted:'Interrumpida',without_observed_end:'Sin final observado'};
const batchOf=r=>r.planned==null?'unknown':r.planned<=0?'0':r.planned<=25?'1-25':r.planned<=100?'26-100':r.planned<=500?'101-500':'501+';
const escape=s=>String(s??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const average=(rs,key)=>{const values=rs.filter(r=>r[key]!=null);return values.length?sum(values,key)/values.length:null;};
const speed=r=>r.photos*1000/r.processing_ms;
const line=(label,value)=>`<div class="stat-line"><span>${label}</span><strong>${value}</strong></div>`;
function render(){
 const cutoff=new Date(data.updatedAt)-Number($('period').value)*86400000;
 selected=data.searches.filter(r=>(platform==='all'||r.platform===platform)&&new Date(r.date)>=cutoff&&($('outcome').value==='all'||r.outcome===$('outcome').value)&&($('version').value==='all'||r.version===$('version').value)&&($('batch').value==='all'||batchOf(r)===$('batch').value));
 $('run-detail').hidden=true;
 const rows=measured(selected),photos=sum(rows,'photos'),ms=sum(rows,'processing_ms'),avg=rows.length?ms/rows.length:null;
 $('cards').innerHTML=[['Velocidad global',ms?n(photos*1000/ms):'—','fotos/s','Fotos totales ÷ tiempo de procesamiento'],['Fotos procesadas',n(sum(selected,'photos'),0),'',`${selected.length} búsquedas seleccionadas`],['Procesamiento medio',avg==null?'—':n(avg/1000),'s','Tiempo de pared por búsqueda medida'],['Promedio por búsqueda',rows.length?n(sum(rows.map(r=>({speed:speed(r)})),'speed')/rows.length):'—','fotos/s','Cada ejecución tiene el mismo peso']].map(([l,v,u,h])=>`<div class="card"><div class="card-label">${l}</div><div class="card-value">${v}<small>${u}</small></div><p>${h}</p></div>`).join('');
 const max=Math.max(1,...rows.map(speed));
 $('chart').innerHTML=rows.length?rows.map((r,i)=>`<div class="chart-row"><span>${r.platform==='ios'?'iOS':'Android'} · ${i+1}</span><div class="track"><div class="bar ${r.platform==='android'?'android':''}" style="width:${speed(r)/max*100}%" title="${n(speed(r))} fotos/s"></div></div><strong>${n(speed(r))} f/s</strong></div>`).join(''):'<p>No hay búsquedas con tiempos medidos para estos filtros.</p>';
 const times=rows.map(r=>r.processing_ms).sort((a,b)=>a-b);const percentile=p=>{if(!times.length)return null;const i=(times.length-1)*p;return times[Math.floor(i)]+(times[Math.ceil(i)]-times[Math.floor(i)])*(i%1);};
 $('timings').innerHTML=line('Mediana de procesamiento',secs(percentile(.5)))+line('Percentil 95',secs(percentile(.95)))+line('Tiempo acumulado',rows.length?secs(ms):'—')+line('Búsquedas con tiempo medido',n(rows.length,0));
 $('platforms').innerHTML=['ios','android'].filter(p=>platform==='all'||p===platform).map(p=>{const rs=rows.filter(r=>r.platform===p),m=sum(rs,'processing_ms');return `<tr><td>${p==='ios'?'iOS':'Android'}</td><td>${rs.length}</td><td>${n(sum(rs,'photos'),0)}</td><td>${rs.length?secs(m):'—'}</td><td>${m?n(sum(rs,'photos')*1000/m):'—'}</td><td>${rs.length?n(rs.reduce((s,r)=>s+speed(r),0)/rs.length):'—'}</td></tr>`;}).join('');
 $('runs').innerHTML=selected.length?[...selected].reverse().map(r=>`<tr><td><button class="run-button" data-run="${selected.indexOf(r)}">${date(r.date)}</button></td><td>${r.platform==='ios'?'iOS':'Android'}</td><td>${escape(r.version)}</td><td>${outcomeLabel[r.outcome]??'Sin dato'}</td><td>${r.photos!=null&&r.planned>0?n(r.photos/r.planned*100)+' %':'—'}</td><td>${n(r.photos,0)} / ${n(r.planned,0)}</td><td>${secs(r.processing_ms)}</td><td>${secs(r.duration_ms)}</td><td>${r.processing_ms>0&&r.photos!=null?n(speed(r)):'—'}</td></tr>`).join(''):'<tr><td colspan="9">Sin ejecuciones en este período.</td></tr>';
 $('row-count').textContent=`${selected.length} ejecuciones`;
 document.querySelectorAll('[data-run]').forEach(b=>b.onclick=()=>showRun(selected[Number(b.dataset.run)]));
 const instrumented=selected.filter(r=>r.cache_hits!=null&&r.cache_misses!=null),hits=sum(instrumented,'cache_hits'),misses=sum(instrumented,'cache_misses');
 $('diagnostics').innerHTML=line('Ejecuciones con datos de caché',`${instrumented.length} / ${selected.length}`)+line('Fotos con caché / sin caché',instrumented.length?`${n(hits,0)} / ${n(misses,0)}`:'Sin medición')+line('Uso de caché',hits+misses?n(hits/(hits+misses)*100)+' %':'Sin medición')+['read_ms','decode_ms','engine_ms'].map((key,i)=>line(['Lectura acumulada','Decodificación acumulada','Motor acumulado'][i],selected.some(r=>r[key]!=null)?secs(sum(selected,key)):'Sin medición')).join('');
 const cancelled=selected.filter(r=>r.outcome==='search_cancelled');
 $('cancellations').innerHTML=line('Canceladas / seleccionadas',`${cancelled.length} / ${selected.length}`)+line('Tiempo medio hasta solicitar cancelar',secs(average(cancelled,'time_to_cancel_ms')))+line('Demora media hasta detenerse',secs(average(cancelled,'cancel_latency_ms')))+line('Cancelaciones con latencia medida',n(cancelled.filter(r=>r.cancel_latency_ms!=null).length,0))+line('Fotos procesadas antes del final',n(sum(cancelled,'photos'),0));
 $('cache-groups').innerHTML=[['Caché total',r=>r.cache_hits===r.photos&&r.cache_hits>0&&r.cache_misses===0],['Sin caché',r=>r.cache_hits===0&&r.cache_misses===r.photos&&r.cache_misses>0],['Mixta',r=>r.cache_hits>0&&r.cache_misses>0&&r.cache_hits+r.cache_misses===r.photos],['Cobertura parcial',r=>r.cache_hits!=null&&r.cache_misses!=null&&r.cache_hits+r.cache_misses<r.photos],['Sin medición',r=>r.cache_hits==null||r.cache_misses==null]].map(([label,accept])=>{const rs=rows.filter(r=>r.outcome==='search_completed'&&accept(r)),ms=sum(rs,'processing_ms');return `<tr><td>${label}</td><td>${rs.length}</td><td>${n(sum(rs,'photos'),0)}</td><td>${ms?n(sum(rs,'photos')*1000/ms):'—'}</td><td>${secs(average(rs,'processing_ms'))}</td></tr>`;}).join('');
 $('batches').innerHTML=['1-25','26-100','101-500','501+'].map(b=>{const rs=rows.filter(r=>batchOf(r)===b&&r.outcome==='search_completed'),ms=sum(rs,'processing_ms');return `<tr><td>${b}</td><td>${rs.length}</td><td>${n(sum(rs,'photos'),0)}</td><td>${ms?n(sum(rs,'photos')*1000/ms):'—'}</td><td>${secs(average(rs,'processing_ms'))}</td></tr>`;}).join('');
 const m=data.metrics,rel=m.related,d=rel.delivery;
 $('usage').innerHTML=[['Instalaciones activas',m.active_installations],['Sesiones iniciadas',m.sessions],['Búsquedas completadas',m.searches_completed],['Búsquedas fallidas',m.searches_failed],['Búsquedas canceladas',m.searches_cancelled]].map(([l,v])=>`<div><strong>${n(v,0)}</strong><span>${l}</span></div>`).join('');
 const distribution=m.subjective_rating_distribution,total=Object.values(distribution).reduce((s,v)=>s+v,0);
 $('ratings').innerHTML=line('Valoración media',`${n(m.subjective_rating_average)} / 5 · ${total} respuestas`)+[5,4,3,2,1].map(s=>`<div class="rating"><span>${s} ★</span><div class="track"><div class="bar" style="width:${total?(distribution[s]??0)/total*100:0}%"></div></div><span>${distribution[s]??0}</span></div>`).join('')+`<p class="note">Cobertura de valoración v2: ${n(rel.rating_coverage*100)} %. Revisiones explícitas: ${rel.reviewed_completions}. Las estrellas son subjetivas; no miden precisión.</p>`;
 $('delivery-values').innerHTML=line('Eventos v2 recibidos',n(d.sample_size,0))+line('Eventos con reintentos',`${n(d.events_retried,0)} · ${d.sample_size?n(d.events_retried/d.sample_size*100):'—'} %`)+line('Retraso medio',secs(d.average_delay_ms))+line('Percentil 95 del retraso',secs(d.p95_delay_ms))+line('Sesiones v2 sin cierre observado',n(rel.sessions.without_observed_end,0));
 $('content').hidden=false;
}
function showRun(r){
 const target=$('run-detail');target.hidden=false;
 target.innerHTML=`<h2>Ejecución · ${date(r.date)} · ${outcomeLabel[r.outcome]??'Sin dato'}</h2><p>${r.platform==='ios'?'iOS':'Android'} · ${escape(r.version)} · ${n(r.photos,0)} de ${n(r.planned,0)} fotos</p>`+
 [['Procesamiento',secs(r.processing_ms)],['Preparación',secs(r.setup_ms)],['Duración total',secs(r.duration_ms)],['Presentación',secs(r.presentation_ms)],['Fotos/s',r.processing_ms>0&&r.photos!=null?n(speed(r)):'Sin medición'],['Lectura',secs(r.read_ms)],['Decodificación',secs(r.decode_ms)],['Motor: detección y comparación',secs(r.engine_ms)],['Fotos con caché',n(r.cache_hits,0)],['Fotos sin caché',n(r.cache_misses,0)],['Solicitud de cancelación desde inicio',secs(r.time_to_cancel_ms)],['Respuesta a cancelación',secs(r.cancel_latency_ms)],['Coincidencias mostradas',n(r.matches,0)],['Fotos ilegibles',n(r.unreadable,0)],['Valoración',r.stars==null?'Sin valoración':n(r.stars)+' / 5'],['Confirmadas / rechazadas',`${n(r.confirmed,0)} / ${n(r.rejected,0)}`],['Categoría de error',escape(r.error_category)],['Retraso de entrega del final',secs(r.delivery_ms)],['Intentos anteriores al envío',n(r.delivery_attempts,0)]].map(([l,v])=>line(l,v)).join('')+'<p class="note">— significa que no se recibió esa medición. No representa cero. Condiciones de suspensión y presión de memoria no están medidas.</p>';
 target.scrollIntoView({behavior:'smooth',block:'start'});
}
async function load(){const btn=$('refresh');btn.disabled=true;btn.textContent='Consultando BD…';$('content').setAttribute('aria-busy','true');$('status').textContent='Extrayendo datos actuales de PostgreSQL…';try{let response,live=false;if(['localhost','127.0.0.1'].includes(location.hostname)){response=await fetch('/api/dashboard',{cache:'no-store',signal:AbortSignal.timeout(20000)});if(!response.ok)throw Error('No se pudo conectar con la API local.');live=true;}else{response=await fetch('data.json',{cache:'no-store'});if(!response.ok)throw Error('No se pudo cargar la captura.');}const next=await response.json();if(!next.metrics||!Array.isArray(next.searches))throw Error('Datos incompletos.');data=next;const previous=$('version').value;$('version').innerHTML='<option value="all">Todas</option>'+[...new Set(data.searches.map(r=>r.version).filter(Boolean))].sort().map(v=>`<option value="${escape(v)}">${escape(v)}</option>`).join('');$('version').value=[...new Set(data.searches.map(r=>r.version))].includes(previous)?previous:'all';render();$('status').textContent=`${live?'● Datos actualizados desde PostgreSQL':'◷ Captura de datos · sin actualización automática'} · ${new Date(data.updatedAt).toLocaleString('es-CO',{timeZone:'America/Bogota',hour12:false})} (Colombia) · Retención: ${data.days} días`;}catch(e){$('status').textContent=`${e.message}${data?' Se conserva la última consulta.':''}`;}finally{btn.disabled=false;btn.textContent='↻ Actualizar desde BD';$('content').setAttribute('aria-busy','false');}}
$('refresh').onclick=load;for(const id of ['period','outcome','version','batch'])$(id).onchange=()=>data&&render();document.querySelectorAll('[data-platform]').forEach(b=>b.onclick=()=>{platform=b.dataset.platform;document.querySelectorAll('[data-platform]').forEach(x=>x.classList.toggle('selected',x===b));if(data)render();});
$('export').onclick=()=>{if(!data)return;const csv=['fecha,plataforma,version,resultado,fotos_previstas,fotos_procesadas,procesamiento_ms,duracion_ms,fotos_por_segundo,cache_hits,cache_misses,lectura_ms,decode_ms,motor_ms,cancelacion_ms',...selected.map(r=>[r.date,r.platform,r.version,r.outcome,r.planned,r.photos,r.processing_ms,r.duration_ms,r.processing_ms>0&&r.photos!=null?speed(r):'',r.cache_hits,r.cache_misses,r.read_ms,r.decode_ms,r.engine_ms,r.cancel_latency_ms].join(','))].join('\n');const url=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='personas-rendimiento.csv';a.click();URL.revokeObjectURL(url);};load();
